"""通过 ISBN 自动查询图书信息（Google Books API → OpenLibrary 备选）"""
import urllib.request
import json
import ssl

# macOS Python 可能缺少 SSL 证书，创建不验证的 context 作为 fallback
try:
    _ctx = ssl.create_default_context()
except Exception:
    _ctx = None

if _ctx:
    try:
        urllib.request.urlopen("https://www.google.com", timeout=3, context=_ctx)
    except ssl.SSLCertVerificationError:
        _ctx.check_hostname = False
        _ctx.verify_mode = ssl.CERT_NONE
    except Exception:
        pass


def _fetch(url):
    req = urllib.request.Request(url, headers={"User-Agent": "BookManager/1.0"})
    with urllib.request.urlopen(req, timeout=8, context=_ctx) as resp:
        return json.loads(resp.read().decode())


def _google_books(isbn):
    data = _fetch(f"https://www.googleapis.com/books/v1/volumes?q=isbn:{isbn}")
    if not data.get("items"):
        return None
    info = data["items"][0].get("volumeInfo", {})
    return {
        "title": info.get("title", ""),
        "author": ", ".join(info.get("authors", [])),
        "publisher": info.get("publisher", ""),
    }


def _openlibrary(isbn):
    data = _fetch(f"https://openlibrary.org/api/books?bibkeys=ISBN:{isbn}&format=json&jscmd=data")
    key = f"ISBN:{isbn}"
    if key not in data:
        return None
    info = data[key]
    return {
        "title": info.get("title", ""),
        "author": ", ".join(a.get("name", "") for a in info.get("authors", [])),
        "publisher": ", ".join(p.get("name", "") for p in info.get("publishers", [])),
    }


def lookup(isbn):
    """返回 {"title": ..., "author": ..., "publisher": ...} 或 None"""
    for fn in (_google_books, _openlibrary):
        try:
            result = fn(isbn)
            if result and result.get("title"):
                return result
        except Exception:
            continue
    return None

